  border-top: 1px solid #edf2f7;
}

.aioq-sidebar-block-title {
  min-height: 28px;
  display: flex;
  align-items: center;
  padding: 0 8px;
  color: #6b7c90;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.aioq-sidebar-agent-list {
  display: grid;
  gap: 2px;
  margin-top: 4px;
